#!/usr/bin/env /usr/bin/python3
"""Offline map of candidate/V2 land changes, with independently checked V7 overlap."""
import argparse,base64,csv,gzip,io,json,hashlib
from collections import defaultdict,Counter
from pathlib import Path
import numpy as np
from PIL import Image
ap=argparse.ArgumentParser();ap.add_argument('--spans',required=True,type=Path);ap.add_argument('--ledger',required=True,type=Path);ap.add_argument('--candidate-dir',required=True,type=Path);ap.add_argument('--source',required=True,type=Path);ap.add_argument('--clusters',required=True,type=Path);ap.add_argument('--output',required=True,type=Path);v=ap.parse_args();SP=v.spans;LED=v.ledger;P=v.candidate_dir;GEO=v.source;OUT=v.output;CLUSTERS=v.clusters;W=131072;H=54614;step=360/W
if OUT.exists():raise RuntimeError('output exists')
rows=defaultdict(list)
with SP.open() as f:
 for r in csv.DictReader(f,delimiter='\t'):
  y,a,b,o,n,s=map(int,(r['row'],r['start'],r['end'],r['reference'],r['candidate'],r['mainland_seed']));rows[y].append((a,b,o,n,s))
spans=[];counts=Counter()
with gzip.open(LED,'rt') as f:
 for line in f:
  rec=json.loads(line);y=rec['row']
  for a,b,o,n,seed in rows.get(y,()):
   def emit(lo,hi,flag):
    if hi>lo:spans.append([y,lo,hi,o,n,flag,1 if seed else 0]);counts[flag]+=hi-lo
   if o<17 or n<17:emit(a,b,2);continue
   cursor=a
   for s in rec['spans']:
    if s['end']<=a:continue
    if s['start']>=b:break
    lo=max(a,s['start']);hi=min(b,s['end'])
    if s['from_code']!=o or s['to_code']!=n:raise ValueError('unexpected V7 transition')
    emit(cursor,lo,0);emit(lo,hi,1);cursor=hi
   emit(cursor,b,0)
if counts!={0:7774,1:42025,2:674}:raise ValueError(f'cell counts mismatch {counts}')
# A compact center-sampled land/water background for visual orientation, not analysis.
rr=np.memmap(P/'rows.u32le',dtype='<u4',mode='r');runs=np.memmap(P/'runs.u32le',dtype='<u4',mode='r').reshape(-1,2);h=600;w=1440;xx=np.floor((np.arange(w)+.5)*W/w).astype('u4');image=np.empty((h,w,3),dtype='u1')
for yy in range(h):
 y=min(H-1,int((yy+.5)*H/h));v=runs[int(rr[y]):int(rr[y+1])];land=v[np.searchsorted(v[:,0],xx,side='right'),1]>0;image[yy]=np.where(land[:,None],[181,197,178],[210,227,235])
buf=io.BytesIO();Image.fromarray(image,'RGB').save(buf,format='PNG',optimize=True);background=base64.b64encode(buf.getvalue()).decode();clusters=json.loads(CLUSTERS.read_bytes())['clusters'];cut=next(f for f in json.loads(GEO.read_bytes())['features'] if f['properties']['cut_id']=='caucasus_blacksea_anapa_to_caspian')['geometry']['coordinates']
html=r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>V2 land comparison</title><style>
*{box-sizing:border-box}body{font:15px system-ui,sans-serif;color:#263648;margin:0;background:#f3f6f7}header{background:#203d51;color:white;padding:20px 24px}h1{font-size:23px;margin:0 0 5px}header p{margin:4px 0;color:#dce9ef}main{display:grid;grid-template-columns:minmax(0,1fr) 335px;gap:16px;padding:16px}section,aside{background:white;border-radius:12px;box-shadow:0 1px 8px #29485718;padding:15px}.toolbar{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-bottom:10px}button,select{font:inherit;padding:7px 10px;border:1px solid #a8bac3;background:#fff;border-radius:7px;cursor:pointer}button:hover{background:#e5f0f3}canvas{width:100%;height:min(64vh,600px);background:#d2e3eb;display:block;cursor:grab;border-radius:8px;touch-action:none}canvas:active{cursor:grabbing}.legend{display:flex;gap:14px;flex-wrap:wrap;margin:12px 0}.sw{display:inline-block;width:11px;height:11px;border-radius:50%;margin-right:5px}.note{font-size:13px;color:#506472;line-height:1.48}.pill{font-size:12px;color:#9b5419;font-weight:700}aside h2{margin:0 0 8px;font-size:17px}.cluster{display:block;text-align:left;width:100%;margin:7px 0;padding:9px;line-height:1.3}.cluster small{display:block;color:#687b85;margin-top:3px}#details{background:#f2f6f7;padding:10px;border-radius:7px;line-height:1.5}.small{font-size:12px;color:#697e88}a{color:#245f86}@media(max-width:850px){main{grid-template-columns:1fr}canvas{height:48vh}aside{order:2}}
</style></head><body><header><h1>Where the provisional land map differs from V2</h1><p>49,799 continent-label differences · 674 separate land/water differences</p><p class="pill">Research comparison · land only · not a reconstructed V2 boundary</p></header><main><section><div class="toolbar"><button id="world">World</button><button id="caucasus">Caucasus</button><button id="plus">＋</button><button id="minus">−</button><label>Show <select id="filter"><option value="all">All differences</option><option value="1">Candidate agrees with V7</option><option value="0">V7 retains V2</option><option value="2">Physical land/water differences</option></select></label><label><input type="checkbox" id="cut" checked> Candidate Caucasus cut</label></div><canvas id="map" aria-label="Interactive map of land differences"></canvas><div class="legend"><span><i class="sw" style="background:#bf3d47"></i>Candidate matches V7 (42,025)</span><span><i class="sw" style="background:#9a55a5"></i>V7 retains V2 (7,774)</span><span><i class="sw" style="background:#067d9d"></i>Physical differences (674)</span></div><p class="note">Drag to pan, scroll or use the buttons to zoom, and click a colored change for its exact grid cell. At world scale gray circles mark cluster locations, while colored cells are enlarged so small differences remain visible. The pale background is a coarse candidate land/water rendering for orientation, not the data used in the comparison.</p><p class="note">V7 overlap comes from a saved land-change ledger independently checked against the V2 and V7 grids. Agreement with V7 identifies a later convention, not an error. The candidate uses later reconstructed cuts and a provisional physical input; the original V2 cut is not recovered.</p></section><aside><h2>Major clusters</h2><div id="clusters"></div><h2>Selected cell</h2><div id="details">Select a change on the map.</div><p class="note">Caucasus: 41,815 of 43,553 seeded Asia→Europe cells in the diagnostic region match V7’s recorded mainland adjustment. The remaining 1,738 are within about 153 m of the candidate cut; their exact cause is unproven.</p><p class="small">Grid 131,072 × 54,614, 0.00274658203125° per cell; centers shown. Areas are illustrative, not legal or official boundaries.</p></aside></main><script>
const DATA=__DATA__, C=DATA.spans, K=DATA.clusters, CUT=DATA.cut, W=131072,H=54614,step=360/W;const canvas=document.getElementById('map'),ctx=canvas.getContext('2d'),details=document.getElementById('details');const back=new Image();back.src='data:image/png;base64,__BACKGROUND__';let cx=W/2,cy=H/2,scale=1,drag=null,filter='all';const labels={17:'Africa',18:'Asia',19:'Europe',20:'North America',21:'South America',22:'Oceania',0:'Water',1:'Water',2:'Water',3:'Water',4:'Water',5:'Water',6:'Water',7:'Water',8:'Water',9:'Water',10:'Water'};const colors=['#9a55a5','#bf3d47','#067d9d'];let width=0,height=0,base=0;
function resize(){let r=canvas.getBoundingClientRect(),d=window.devicePixelRatio||1;canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);ctx.setTransform(d,0,0,d,0,0);width=r.width;height=r.height;base=Math.min(width/W,height/H);draw()}
function screen(x,y){let k=base*scale;return [width/2+(x-cx)*k,height/2+(y-cy)*k]}function coord(sx,sy){let k=base*scale;return [cx+(sx-width/2)/k,cy+(sy-height/2)/k]}
function draw(){if(!width)return;ctx.clearRect(0,0,width,height);let [x,y]=screen(0,0),k=base*scale;ctx.drawImage(back,x,y,W*k,H*k);if(document.getElementById('cut').checked&&scale>5){ctx.beginPath();CUT.forEach(([lon,lat],i)=>{let [px,py]=screen((lon+180)/step,(90-lat)/step);i?ctx.lineTo(px,py):ctx.moveTo(px,py)});ctx.strokeStyle='#1e6f47';ctx.lineWidth=1.5;ctx.stroke()}
for(const [row,a,b,old,nw,flag] of C){if(filter!=='all'&&Number(filter)!==flag)continue;let [px,py]=screen(a,row);let len=(b-a)*k;if(py<-3||py>height+3||px>width+3||px+len<-3)continue;ctx.fillStyle=colors[flag];let size=Math.max(1.1,k);ctx.fillRect(px,py,Math.max(size,len),size)}
if(scale<4){for(let i=0;i<Math.min(K.length,12);i++){let c=K[i];if(filter!=='all'&&((filter==='2')!==(c.kind==='physical')))continue;let e=c.extent,[px,py]=screen(((e.west+e.east)/2+180)/step,(90-(e.north+e.south)/2)/step);ctx.beginPath();ctx.arc(px,py,Math.max(3,Math.min(10,Math.log10(c.cells+1)*2)),0,2*Math.PI);ctx.fillStyle=c.kind==='physical'?colors[2]:'#43576a';ctx.globalAlpha=.75;ctx.fill();ctx.globalAlpha=1;}}
}
function zoom(f,sx=width/2,sy=height/2){let [x,y]=coord(sx,sy);scale=Math.max(1,Math.min(2000,scale*f));let [xx,yy]=coord(sx,sy);cx+=x-xx;cy+=y-yy;draw()}
function focus(c){let e=c.extent;cx=((e.west+e.east)/2+180)/step;cy=(90-(e.north+e.south)/2)/step;let dx=Math.max((e.east-e.west)/step,50),dy=Math.max((e.north-e.south)/step,50);scale=Math.max(1,Math.min(1200,Math.min(width/(dx*1.6),height/(dy*1.6))/base));draw()}
const names=['Caucasus','Ural Mountains','Ural River and Caspian lowlands','Hudson Strait physical changes','Panama–Colombia','Southern Urals'];let box=document.getElementById('clusters');K.slice(0,12).forEach((c,i)=>{let btn=document.createElement('button');btn.className='cluster';btn.innerHTML='<strong>'+(names[i]||('Cluster '+(i+1)))+'</strong> · '+c.cells.toLocaleString()+' cells<small>'+c.kind+' · '+c.extent.west.toFixed(2)+'° to '+c.extent.east.toFixed(2)+'° longitude</small>';btn.onclick=()=>focus(c);box.appendChild(btn)});
canvas.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,cx,cy,moved:false};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drag)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>3)drag.moved=true;cx=drag.cx-dx/(base*scale);cy=drag.cy-dy/(base*scale);draw()});canvas.addEventListener('pointerup',e=>{if(!drag)return;if(!drag.moved){let rect=canvas.getBoundingClientRect(),[x,y]=coord(e.clientX-rect.left,e.clientY-rect.top),best=null,dist=Infinity;for(const s of C){if(filter!=='all'&&Number(filter)!==s[5])continue;let dx=Math.max(s[1]-x,0,x-(s[2]-1)),dy=Math.abs(s[0]-y),d=Math.hypot(dx,dy);if(d<dist){dist=d;best=s}}if(best&&dist*base*scale<12){let [row,a,b,o,n,flag,seed]=best,col=Math.max(a,Math.min(b-1,Math.round(x))),lon=-180+(col+.5)*step,lat=90-(row+.5)*step;details.innerHTML='<strong>'+labels[o]+' → '+labels[n]+'</strong><br>Latitude '+lat.toFixed(6)+'°, longitude '+lon.toFixed(6)+'°<br>Row '+row+', column '+col+'<br>'+(flag===1?'V7 matches candidate':flag===0?'V7 retains V2':'Physical land/water difference')+'<br>'+(seed?'Candidate mainland seed':'Outside candidate mainland seed')+'<br><a target="_blank" rel="noopener" href="https://www.openstreetmap.org/?mlat='+lat+'&mlon='+lon+'#map=12/'+lat+'/'+lon+'">Open location in OpenStreetMap ↗</a>'}}drag=null});canvas.addEventListener('wheel',e=>{e.preventDefault();let r=canvas.getBoundingClientRect();zoom(e.deltaY<0?1.3:1/1.3,e.clientX-r.left,e.clientY-r.top)},{passive:false});document.getElementById('plus').onclick=()=>zoom(1.5);document.getElementById('minus').onclick=()=>zoom(1/1.5);document.getElementById('world').onclick=()=>{cx=W/2;cy=H/2;scale=1;draw()};document.getElementById('caucasus').onclick=()=>focus(K[0]);document.getElementById('filter').onchange=e=>{filter=e.target.value;draw()};document.getElementById('cut').onchange=draw;back.onload=resize;window.addEventListener('resize',resize);resize();
</script></body></html>'''
payload={'spans':spans,'clusters':clusters,'cut':cut};html=html.replace('__DATA__',json.dumps(payload,separators=(',',':'))).replace('__BACKGROUND__',background);OUT.write_text(html);print(json.dumps({'file':str(OUT),'bytes':OUT.stat().st_size,'spans':len(spans),'counts':dict(counts),'sha256':hashlib.sha256(OUT.read_bytes()).hexdigest(),'land_background':'coarse center sampled candidate land/water'}))
